import { createTheme } from '@mui/material/styles';

const theme = createTheme({
  palette: {
    primary: {
      main: '#2D5A8C',  // Azul corporativo
      dark: '#1C3C64',  // Azul oscuro
      light: '#4A7BB8', // Azul claro
      contrastText: '#ffffff'
    },
    secondary: {
      main: '#4CAF50',  // Verde para acentos
      dark: '#388E3C',
      light: '#81C784',
      contrastText: '#ffffff'
    },
    background: {
      default: '#f5f7fa',  // Fondo claro
      paper: '#ffffff'     // Fondo de tarjetas
    },
    text: {
      primary: '#263238',   // Texto principal oscuro
      secondary: '#546e7a', // Texto secundario
      disabled: '#90a4ae'
    },
    divider: '#e0e0e0'     // Color para bordes
  },
  typography: {
    fontFamily: [
      '"Roboto"',
      '"Helvetica"',
      '"Arial"',
      'sans-serif'
    ].join(','),
    h1: {
      fontWeight: 300,
      fontSize: '3.5rem',
      lineHeight: 1.2
    },
    h2: {
      fontWeight: 300,
      fontSize: '2.5rem',
      lineHeight: 1.3
    },
    h3: {
      fontWeight: 400,
      fontSize: '2rem',
      lineHeight: 1.3
    },
    h4: {
      fontWeight: 400,
      fontSize: '1.75rem',
      lineHeight: 1.4
    },
    h5: {
      fontWeight: 500,
      fontSize: '1.5rem'
    },
    h6: {
      fontWeight: 500,
      fontSize: '1.25rem'
    },
    body1: {
      fontSize: '1rem',
      lineHeight: 1.6
    },
    button: {
      textTransform: 'none', // Para que los botones no estén en mayúsculas
      fontWeight: 500
    }
  },
  shape: {
    borderRadius: 4 // Bordes ligeramente redondeados
  },
  components: {
    MuiButton: {
      styleOverrides: {
        root: {
          padding: '8px 22px'
        }
      }
    },
    MuiPaper: {
      styleOverrides: {
        root: {
          transition: 'all 0.3s ease'
        }
      }
    },
    MuiListItemIcon: {
      styleOverrides: {
        root: {
          minWidth: '40px'
        }
      }
    }
  }
});

export default theme;
